import * as THREE from 'three';

export function buildConstellation({ planetRadius = 5, sats }) {
  const group = new THREE.Group(); // root
  const built = sats.map(spec => {
    const planeGroup = new THREE.Group();
    const orbitGroup = new THREE.Group();
    const mesh = new THREE.Mesh(new THREE.SphereGeometry(0.2, 16, 16));
    mesh.position.x = planetRadius + spec.altitude;
    orbitGroup.add(mesh);
    planeGroup.add(orbitGroup);
    planeGroup.rotation.x = THREE.MathUtils.degToRad(spec.inclinationDeg);
    group.add(planeGroup);
    return { name: spec.name, spec, planeGroup, orbitGroup, mesh };
  });
  return { group, planetRadius, sats: built };
}

export function updateConstellation(constellation, t) {
  for (const sat of constellation.sats) {
    const { periodSec, phaseDeg } = sat.spec;
    const phase = THREE.MathUtils.degToRad(phaseDeg);
    sat.orbitGroup.rotation.y = phase + (2 * Math.PI * t) / periodSec;
    // update world matrices
  }
  constellation.group.updateMatrixWorld(true);
}
```

