import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { buildConstellation, updateConstellation } from '../src/constellation.js';

function worldPos(constellation, sat, t) {
  updateConstellation(constellation, t);
  return sat.mesh.getWorldPosition(new THREE.Vector3());
}

describe('buildConstellation / updateConstellation', () => {
  it('keeps a zero-inclination satellite in the equatorial plane and on a circular orbit', () => {
    const planetRadius = 5;
    const altitude = 3;
    const periodSec = 100;

    const c = buildConstellation({
      planetRadius,
      sats: [
        { name: 'eq', altitude, inclinationDeg: 0, phaseDeg: 0, periodSec }
      ]
    });
    const sat = c.sats[0];
    const expectedR = planetRadius + altitude;

    for (let i = 0; i <= 12; i++) {
      const t = (i / 12) * periodSec;
      const p = worldPos(c, sat, t);
      expect(Math.abs(p.y)).toBeLessThanOrEqual(1e-6);
      expect(p.length()).toBeCloseTo(expectedR, 6);
    }
  });

  it('at inclination 90 the quarter-period position is at the pole (zero x-z component), with max |y| equal to the orbital radius', () => {
    const planetRadius = 5;
    const altitude = 4;
    const periodSec = 80;
    const expectedR = planetRadius + altitude;

    const c = buildConstellation({
      planetRadius,
      sats: [
        { name: 'polar', altitude, inclinationDeg: 90, phaseDeg: 0, periodSec }
      ]
    });
    const sat = c.sats[0];

    // Quarter period: motion through the pole -> no x-z plane component.
    const q = worldPos(c, sat, periodSec / 4);
    const horizontal = Math.hypot(q.x, q.z);
    expect(horizontal).toBeLessThanOrEqual(1e-6);
    expect(q.y).toBeCloseTo(expectedR, 6);

    // Dense sampling: max |y| equals orbital radius within 1e-6.
    let maxY = 0;
    for (let i = 0; i < 2000; i++) {
      const p = worldPos(c, sat, (i / 2000) * periodSec);
      maxY = Math.max(maxY, Math.abs(p.y));
    }
    expect(maxY).toBeCloseTo(expectedR, 6);
  });

  it('two satellites phased 0/180 in a shared plane and period stay diametrically opposite', () => {
    const planetRadius = 5;
    const altitude = 2;
    const periodSec = 120;

    const c = buildConstellation({
      planetRadius,
      sats: [
        { name: 'a', altitude, inclinationDeg: 45, phaseDeg: 0, periodSec },
        { name: 'b', altitude, inclinationDeg: 45, phaseDeg: 180, periodSec }
      ]
    });
    const [a, b] = c.sats;

    for (let i = 0; i < 50; i++) {
      const t = (i / 50) * periodSec;
      const pa = worldPos(c, a, t);
      const pb = worldPos(c, b, t);
      const sum = pa.clone().add(pb);
      expect(sum.length()).toBeLessThanOrEqual(1e-6);
    }
  });

  it('t = 0 and t = period give identical positions', () => {
    const c = buildConstellation({
      sats: [
        { name: 's', altitude: 7, inclinationDeg: 63.4, phaseDeg: 37, periodSec: 90 }
      ]
    });
    const sat = c.sats[0];

    const p0 = worldPos(c, sat, 0);
    const pT = worldPos(c, sat, 90);
    expect(p0.distanceTo(pT)).toBeLessThanOrEqual(1e-9);
  });
});

