import * as THREE from 'three';

const degToRad = THREE.MathUtils.degToRad;

/**
 * Builds a satellite constellation scene graph.
 *
 * Each satellite is structured as:
 *   planeGroup (rotation.x = inclination) -> orbitGroup -> mesh at x = planetRadius + altitude
 *
 * @param {object} options
 * @param {number} [options.planetRadius=5]
 * @param {Array<{name: string, altitude: number, inclinationDeg: number, phaseDeg: number, periodSec: number}>} options.sats
 * @returns {{group: THREE.Group, planetRadius: number, sats: Array}}
 */
export function buildConstellation({ planetRadius = 5, sats }) {
  const group = new THREE.Group();

  const built = sats.map((spec) => {
    const planeGroup = new THREE.Group();
    const orbitGroup = new THREE.Group();

    const geometry = new THREE.SphereGeometry(0.2, 16, 16);
    const material = new THREE.MeshBasicMaterial();
    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.x = planetRadius + spec.altitude;

    orbitGroup.add(mesh);
    planeGroup.add(orbitGroup);
    planeGroup.rotation.x = degToRad(spec.inclinationDeg);
    group.add(planeGroup);

    return { name: spec.name, spec, planeGroup, orbitGroup, mesh };
  });

  return { group, planetRadius, sats: built };
}

/**
 * Advances the constellation to time t (seconds).
 * Sets each orbitGroup.rotation.y = phase + 2*PI*t/period.
 */
export function updateConstellation(constellation, t) {
  for (const sat of constellation.sats) {
    const { phaseDeg, periodSec } = sat.spec;
    sat.orbitGroup.rotation.y =
      degToRad(phaseDeg) + (2 * Math.PI * t) / periodSec;
  }
  constellation.group.updateMatrixWorld(true);
}

